'use strict';
// Finite deposits, village production, professions and material-based construction.
raceNames.goblin='Goblin';raceNames.beastkin='Tộc Thú';traitNames.miner='Thợ mỏ bẩm sinh';traitNames.forager='Kiếm ăn giỏi';
const resourceNames={stone:'Đá',coal:'Than',iron:'Sắt',copper:'Đồng',gold:'Vàng',crystal:'Tinh thể',weapon:'Vũ khí',armor:'Giáp',tool:'Công cụ'};
const oreKinds=['stone','coal','iron','copper','gold','crystal'];
const oreSprites={iron:2,coal:3,copper:4,gold:5,crystal:6,stone:7};
const jobNames={miner:'Thợ mỏ',lumberjack:'Tiều phu',farmer:'Nông dân',smith:'Thợ rèn',merchant:'Thương nhân',builder:'Thợ xây'};
const buildingDefs={mine:{name:'Mỏ khai thác',sprite:8,cost:{wood:12,stone:10},tech:0},forge:{name:'Lò rèn',sprite:9,cost:{wood:15,stone:15,copper:4},tech:1},warehouse:{name:'Kho hàng',sprite:10,cost:{wood:20,stone:12},tech:0},market:{name:'Chợ',sprite:11,cost:{wood:18,stone:8,gold:2},tech:1},tower:{name:'Tháp canh',sprite:12,cost:{wood:15,stone:20,iron:4},tech:1},well:{name:'Giếng nước',sprite:13,cost:{wood:5,stone:12},tech:0},fishery:{name:'Nhà đánh cá',sprite:14,cost:{wood:18,stone:5},tech:0},workshop:{name:'Nhà nghiên cứu',sprite:10,cost:{wood:15,stone:8,copper:4},tech:1}};
const craftDefs={tool:{name:'Công cụ',cost:{iron:2,coal:1,wood:1}},weapon:{name:'Vũ khí',cost:{iron:3,coal:2,wood:1}},armor:{name:'Giáp',cost:{iron:4,coal:2}}};
const ecoOld={newWorld,spawn,enrich,simulate,ecology,applyTool,draw,drawPerson,showSelection,snapshot,restore,renderKingdoms,damage};
buildingDefs.workshop.cost={wood:15,stone:8,copper:4,gold:2,crystal:4};
let buildings=[],productionTimer=0,tradeTimer=0,autoBuildTimer=0,economyView=null;
const economySprite=new Image();let economySpriteReady=false;economySprite.src='assets/economy-sprites-v2.png';economySprite.onload=()=>{economySpriteReady=true;};
function drawEconomySprite(n,x,y,size){if(!economySpriteReady)return;const cell=economySprite.width/4;ctx.drawImage(economySprite,(n%4)*cell,Math.floor(n/4)*cell,cell,cell,x-size/2,y-size*.72,size,size);}
drawPerson=function(e,bob){if(['goblin','beastkin'].includes(e.race)&&economySpriteReady)drawEconomySprite(e.race==='goblin'?0:1,e.x,e.y+bob,1.7);else ecoOld.drawPerson(e,bob);};
function hasBuilding(v,kind){return buildings.some(b=>b.village===v.id&&b.kind===kind&&b.hp>0);}
function resourceCap(v){return hasBuilding(v,'warehouse')?400:120;}
function readMaterial(v,key){return key==='wood'?v.wood:key==='food'?v.food:v.stock[key]||0;}
function changeMaterial(v,key,amount){if(key==='wood')v.wood=Math.max(0,v.wood+amount);else if(key==='food')v.food=Math.max(0,v.food+amount);else v.stock[key]=Math.max(0,v.stock[key]+amount);}
function canAfford(v,cost){return Object.entries(cost).every(([key,amount])=>readMaterial(v,key)>=amount);}
function spendMaterials(v,cost){if(!canAfford(v,cost))return false;for(const [key,amount] of Object.entries(cost))changeMaterial(v,key,-amount);return true;}
function ensureVillageEconomy(v){if(!v.stock)v.stock={stone:8,coal:4,iron:4,copper:0,gold:0,crystal:0,weapon:0,armor:0,tool:0};v.autoBuild??=true;v.focus??='balanced';v.production??=0;}
enrich=function(e,race){ecoOld.enrich(e,race);if(e.kind!=='human')return;e.job??=(e.race==='goblin'||e.race==='dwarf')&&e.id%3===0?'miner':['miner','lumberjack','farmer','smith','merchant','builder'][e.id%6];e.cargo??=null;e.equipment??={weapon:0,armor:0,tool:0};};
spawn=function(kind,x,y,village=null){const e=ecoOld.spawn(kind,x,y,village);if(e)enrich(e,e.race);return e;};
function depositAt(x,y,type,amount=60){if(!inside(x,y)||grid[idx(x,y)].t===0||!oreKinds.includes(type))return false;grid[idx(x,y)].ore={type,amount,initial:amount};return true;}
function seedDeposits(){for(let i=0;i<N;i++){const t=grid[i];if(t.t===0||t.ore)continue;const hash=((i*73+Math.floor(t.shade*100000))%1000)/1000;if(t.t===4&&hash<.68||t.t!==4&&hash<.013){const type=oreKinds[(i*17+Math.floor(t.shade*1000))%6];t.ore={type,amount:40+(i%7)*12,initial:40+(i%7)*12};}}
for(const v of villages){ensureVillageEconomy(v);for(let k=0;k<6;k++){const target=findLand(v.x+Math.cos(k*Math.PI/3)*6,v.y+Math.sin(k*Math.PI/3)*6);if(target)depositAt(target.x,target.y,oreKinds[k],70);}}}
function initEconomy(seedOre=false){for(const v of villages)ensureVillageEconomy(v);for(const e of humans())enrich(e,e.race);if(seedOre)seedDeposits();}
newWorld=function(s=seed,type='islands'){buildings=[];productionTimer=tradeTimer=autoBuildTimer=0;ecoOld.newWorld(s,type);initEconomy(true);renderEconomyHud();};
function costText(cost){return Object.entries(cost).map(([key,n])=>n+' '+(key==='wood'?'gỗ':key==='food'?'thức ăn':resourceNames[key].toLowerCase())).join(', ');}
function buildStructure(villageId,kind,x=null,y=null){const v=villages.find(v=>v.id===Number(villageId)),def=buildingDefs[kind];if(!v||!def)throw Error('Công trình hoặc khu định cư không tồn tại.');ensureVillageEconomy(v);if(!humans().some(e=>e.village===v.id))throw Error('Khu định cư không còn cư dân.');if(hasBuilding(v,kind))throw Error('Khu định cư đã có '+def.name.toLowerCase()+'.');if(v.tech<def.tech)throw Error('Cần công nghệ '+techNames[def.tech]+'.');if(!canAfford(v,def.cost))throw Error('Thiếu nguyên liệu: '+costText(def.cost));let location=null;
for(let k=0;k<32;k++){const xx=x??v.x+Math.cos(k*1.7)*(4+k%5),yy=y??v.y+Math.sin(k*1.7)*(4+k%5);if(walkable(xx,yy)&&Math.hypot(xx-v.x,yy-v.y)<=14&&houses.every(h=>Math.hypot(xx-h.x,yy-h.y)>2.5)&&buildings.every(b=>Math.hypot(xx-b.x,yy-b.y)>3)){if(kind==='fishery'&&!hasWaterNear(xx,yy,6)){if(x!==null)break;continue;}location={x:xx,y:yy};break;}if(x!==null)break;}
if(!location)throw Error(kind==='fishery'?'Nhà đánh cá cần đất gần biển.':'Không đủ chỗ xây trên đất gần khu định cư.');spendMaterials(v,def.cost);const b={id:idCounter++,kind,village:v.id,x:location.x,y:location.y,hp:100};buildings.push(b);const t=grid[idx(b.x,b.y)];t.obj=-1;t.t=1;t.ore=null;remember(v.name+' dựng '+def.name.toLowerCase()+'.','civil');renderEconomyHud();return b;}
function hasWaterNear(x,y,r){for(let yy=Math.max(0,Math.floor(y-r));yy<Math.min(H,y+r);yy++)for(let xx=Math.max(0,Math.floor(x-r));xx<Math.min(W,x+r);xx++)if(grid[idx(xx,yy)].t===0)return true;return false;}
function craft(villageId,item){const v=villages.find(v=>v.id===Number(villageId)),recipe=craftDefs[item];if(!v||!recipe)throw Error('Công thức không hợp lệ.');ensureVillageEconomy(v);if(!hasBuilding(v,'forge'))throw Error('Cần xây lò rèn trước.');if(v.stock[item]>=resourceCap(v))throw Error('Kho đã đầy.');if(!spendMaterials(v,recipe.cost))throw Error('Thiếu nguyên liệu: '+costText(recipe.cost));v.stock[item]++;v.production++;return true;}
function equipPeople(v){for(const e of humans().filter(e=>e.village===v.id)){if(e.job==='miner'||e.job==='lumberjack'){if(!e.equipment.tool&&v.stock.tool>=1){e.equipment.tool=1;v.stock.tool--;}}if(e.soldier||e.traits.includes('strong')){for(const item of ['weapon','armor'])if(!e.equipment[item]&&v.stock[item]>=1){e.equipment[item]=1;v.stock[item]--;}}}}
function depositCargo(e,v){if(!e.cargo)return;const space=resourceCap(v)-v.stock[e.cargo.type],amount=Math.min(space,e.cargo.amount);if(amount>0){v.stock[e.cargo.type]+=amount;v.production+=amount;e.cargo.amount-=amount;}if(e.cargo.amount<=.001)e.cargo=null;}
function resourceTarget(e,v){const radius=hasBuilding(v,'mine')?22:15,candidates=[];for(let yy=Math.max(0,Math.floor(v.y-radius));yy<Math.min(H,v.y+radius);yy++)for(let xx=Math.max(0,Math.floor(v.x-radius));xx<Math.min(W,v.x+radius);xx++){const ore=grid[idx(xx,yy)].ore;if(!ore||ore.amount<=0||v.stock[ore.type]>=resourceCap(v)||Math.hypot(xx-v.x,yy-v.y)>radius)continue;candidates.push({x:xx+.5,y:yy+.5,index:idx(xx,yy),ore});}
candidates.sort((a,b)=>{const needed=t=>t.ore.type==='stone'&&!hasBuilding(v,'mine')?8:['copper','coal','iron'].includes(t.ore.type)?4:0;return Math.hypot(a.x-e.x,a.y-e.y)-needed(a)-Math.hypot(b.x-e.x,b.y-e.y)+needed(b);});for(const c of candidates.slice(0,10)){const stand=walkable(c.x,c.y)?{x:c.x,y:c.y}:[[1,0],[-1,0],[0,1],[0,-1]].map(([dx,dy])=>({x:c.x+dx,y:c.y+dy})).find(p=>walkable(p.x,p.y));if(stand&&(Math.hypot(e.x-stand.x,e.y-stand.y)<1.6||pathStep(e,stand,false)))return{...c,stand};}return null;}
function miningStep(e,v,dt){if(e.cargo){if(Math.hypot(e.x-v.x,e.y-v.y)<2.5)depositCargo(e,v);else{const step=pathStep(e,v,false);if(step){e.tx=step.x;e.ty=step.y;}}return;}const target=resourceTarget(e,v);if(!target)return;const distance=Math.hypot(e.x-target.stand.x,e.y-target.stand.y);if(distance>1.6){const step=pathStep(e,target.stand,false);if(step){e.tx=step.x;e.ty=step.y;}return;}const racial=e.race==='goblin'?1.5:e.race==='dwarf'?1.35:1,skill=e.traits.includes('miner')?1.25:1,quantity=Math.min(target.ore.amount,dt*1.2*racial*skill*(e.equipment.tool?1.4:1)*(hasBuilding(v,'mine')?1.25:1));if(quantity<=0)return;target.ore.amount-=quantity;e.cargo={type:target.ore.type,amount:quantity};e.tx=e.x;e.ty=e.y;}
function productionStep(dt){initEconomy();for(const e of humans()){if(e.age<2||e.soldier||e.id===possessed||e.hunger<40||(typeof isOnDuty==='function'&&!isOnDuty(e)))continue;if(typeof residentLaborStep==='function'&&['farmer','lumberjack'].includes(e.job))continue;const workDt=dt*(typeof laborRate==='function'?laborRate(e):1);const v=villages.find(v=>v.id===e.village);if(!v)continue;if(e.job==='miner')miningStep(e,v,workDt);else if(e.job==='lumberjack'){const t=grid[idx(e.x,e.y)];if(t.t===3){v.wood=Math.min(500,v.wood+workDt*(e.equipment.tool?1.3:.8));t.food=Math.max(0,t.food-workDt*.2);}}else if(e.job==='farmer'){const t=grid[idx(e.x,e.y)];if(t.t===5||t.t===1){v.food=Math.min(10000,v.food+workDt*(e.race==='beastkin'?1.5:.7));t.food=Math.min(t.t===5?45:8,t.food+workDt*.5);}}}
for(const v of villages){if(typeof residentLaborStep!=='function'&&hasBuilding(v,'fishery'))v.food=Math.min(10000,v.food+dt*2);if(hasBuilding(v,'well'))for(const e of humans().filter(e=>e.village===v.id&&Math.hypot(e.x-v.x,e.y-v.y)<10))e.hp=Math.min(100,e.hp+dt*.12);if(hasBuilding(v,'workshop'))v.knowledge=Math.min(2000,v.knowledge+dt*.02);if(hasBuilding(v,'tower'))for(const enemy of humans().filter(e=>atWar(v.kingdom,kingdomOf(e))&&Math.hypot(e.x-v.x,e.y-v.y)<9))damage(enemy,dt*2);if(hasBuilding(v,'forge')&&humans().some(e=>e.village===v.id&&e.job==='smith'&&(typeof lifeFor!=='function'||lifeFor(e).action==='craft'&&buildings.some(b=>b.village===v.id&&b.kind==='forge'&&Math.hypot(b.x-e.x,b.y-e.y)<2))&&(typeof isOnDuty!=='function'||isOnDuty(e)))){const order=['tool','weapon','armor'];for(const item of order)if(v.stock[item]<2&&canAfford(v,craftDefs[item].cost)){craft(v.id,item);break;}}equipPeople(v);}
for(const b of buildings){const t=grid[idx(b.x,b.y)];if(t.t===0||t.t===4)b.hp=0;else if(t.fire)b.hp=Math.max(0,b.hp-dt*18);}const lost=buildings.filter(b=>b.hp<=0);for(const b of lost)remember(buildingDefs[b.kind].name+' của '+villages.find(v=>v.id===b.village)?.name+' bị phá hủy.','civil');buildings=buildings.filter(b=>b.hp>0);entities=entities.filter(e=>e.hp>0);renderEconomyHud();if($('economy-dialog').open)renderEconomy();}
function tradeResources(){for(let i=0;i<villages.length;i++)for(let j=i+1;j<villages.length;j++){const a=villages[i],b=villages[j];if(!hasBuilding(a,'market')||!hasBuilding(b,'market')||atWar(a.kingdom,b.kingdom)||Math.hypot(a.x-b.x,a.y-b.y)>50||!humans().some(e=>[a.id,b.id].includes(e.village)&&e.job==='merchant'&&(typeof isOnDuty!=='function'||isOnDuty(e))))continue;for(const type of oreKinds){const diff=a.stock[type]-b.stock[type];if(Math.abs(diff)<12)continue;const from=diff>0?a:b,to=diff>0?b:a,amount=Math.min(3,Math.abs(diff)/4,resourceCap(to)-to.stock[type]);if(amount>0){from.stock[type]-=amount;to.stock[type]+=amount;}}}}
function automaticConstruction(){for(const v of villages){if(!v.autoBuild||!humans().some(e=>e.village===v.id&&e.job==='builder'&&(typeof isOnDuty!=='function'||isOnDuty(e))))continue;const order=v.focus==='mining'?['mine','warehouse','forge','market','well','tower','workshop','fishery']:v.focus==='farming'?['well','fishery','warehouse','mine','forge','market','tower','workshop']:['mine','well','forge','warehouse','market','tower','workshop','fishery'];for(const kind of order)if(!hasBuilding(v,kind)&&v.tech>=buildingDefs[kind].tech&&canAfford(v,buildingDefs[kind].cost)){try{buildStructure(v.id,kind);break;}catch{}}}}
simulate=function(dt){ecoOld.simulate(dt);for(const e of humans()){const t=grid[idx(e.x,e.y)];if(typeof mindFor!=='function'&&t.road&&e.id!==possessed){const dx=e.tx-e.x,dy=e.ty-e.y,len=Math.hypot(dx,dy);if(len>.02){const step=Math.min(len,dt*.7),x=e.x+dx/len*step,y=e.y+dy/len*step;if(walkable(x,y)){e.x=x;e.y=y;}}}}productionTimer+=dt;tradeTimer+=dt;autoBuildTimer+=dt;if(productionTimer>=2){productionTimer%=2;productionStep(2);}if(tradeTimer>=10){tradeTimer%=10;tradeResources();}if(autoBuildTimer>=8){autoBuildTimer%=8;automaticConstruction();}};
damage=function(e,value){ecoOld.damage(e,value*(e.equipment?.armor?.75:1));};
// Houses now consume stone; blocked construction refunds the core's food and wood.
ecology=function(){for(const v of villages)ensureVillageEconomy(v);const prior=new Set(houses.map(h=>h.id)),targets=humans().filter(e=>e.job==='miner'&&!e.soldier&&e.hunger>=40).map(e=>[e,e.tx,e.ty]);ecoOld.ecology();for(const [e,x,y] of targets){e.tx=x;e.ty=y;}for(const h of houses)if(!prior.has(h.id)){const v=villages.find(v=>v.id===h.village);if(v)v.stock.stone=Math.max(0,v.stock.stone-3);}};

groups.life.push(['goblin','⛏','Goblin','Khai thác nhanh hơn, có thiên hướng làm thợ mỏ.'],['beastkin','🦊','Tộc Thú','Kiếm ăn và canh tác nhanh hơn.']);
groups.resources=oreKinds.map(k=>['ore-'+k,'◆',resourceNames[k],'Đặt mạch quặng hữu hạn lên đất.']);
groups.resources.push(['prospect','⌕','Thăm dò','Xem loại và trữ lượng khoáng sản.']);
groups.build=Object.entries(buildingDefs).map(([k,d])=>['build-'+k,'⌂',d.name,costText(d.cost)]);
groups.build.push(['road','═','Đường','Cư dân di chuyển nhanh hơn trên đường.']);
applyTool=function(x,y){if(!inside(x,y))return;if(['goblin','beastkin'].includes(tool)){if(!walkable(x,y))return;chosenRace=tool;const e=spawn('human',x,y);if(e){enrich(e,tool);e.age=18;e.job=tool==='goblin'?'miner':'farmer';const trait=tool==='goblin'?'miner':'forager';if(!e.traits.includes(trait))e.traits.push(trait);const v=nearestVillage(e);if(v&&Math.hypot(v.x-x,v.y-y)<16)e.village=v.id;}chosenRace='human';return;}
if(tool.startsWith('ore-')){const type=tool.slice(4);if(!oreKinds.includes(type))return;for(let yy=Math.floor(y-radius);yy<=y+radius;yy++)for(let xx=Math.floor(x-radius);xx<=x+radius;xx++)if(inside(xx,yy)&&Math.hypot(xx-x,yy-y)<=radius)depositAt(xx,yy,type,80);return;}
if(tool==='prospect'){const ore=grid[idx(x,y)].ore;toast(ore?resourceNames[ore.type]+': '+ore.amount.toFixed(1)+' / '+ore.initial:'Không có khoáng sản tại đây.');return;}
if(tool.startsWith('build-')){const v=nearestVillage(x,y);try{if(!v||Math.hypot(v.x-x,v.y-y)>22)throw Error('Hãy xây gần một khu định cư.');buildStructure(v.id,tool.slice(6),x,y);}catch(e){toast(e.message);}return;}
if(tool==='road'){for(let yy=Math.floor(y-radius);yy<=y+radius;yy++)for(let xx=Math.floor(x-radius);xx<=x+radius;xx++)if(inside(xx,yy)&&walkable(xx,yy)&&Math.hypot(xx-x,yy-y)<=radius)grid[idx(xx,yy)].road=true;return;}
ecoOld.applyTool(x,y);for(let yy=Math.max(0,Math.floor(y-radius));yy<Math.min(H,y+radius+1);yy++)for(let xx=Math.max(0,Math.floor(x-radius));xx<Math.min(W,x+radius+1);xx++){const t=grid[idx(xx,yy)];if(t.t===0||tool==='erase'){t.ore=null;t.road=false;}}if(tool==='erase')buildings=buildings.filter(b=>Math.hypot(b.x-x,b.y-y)>radius);};
draw=function(){ecoOld.draw();const s=base*zoom;ctx.save();ctx.translate((cw-W*s)/2+panX,(ch-H*s)/2+panY);ctx.scale(s,s);if(typeof paintCachedMap!=='function')for(let y=0;y<H;y++)for(let x=0;x<W;x++){const t=grid[idx(x,y)];if(t.road){ctx.fillStyle='#bca77788';ctx.fillRect(x+.25,y+.3,.5,.4);}if(t.ore?.amount>0)drawEconomySprite(oreSprites[t.ore.type],x+.5,y+.5,1.65);}if(typeof paintDepthWorld!=='function')for(const b of buildings)drawEconomySprite(buildingDefs[b.kind].sprite,b.x,b.y,3.8);ctx.font='.9px Segoe UI';ctx.textAlign='center';for(const e of humans())if(e.cargo&&(typeof isResidentIndoors!=='function'||!isResidentIndoors(e))){ctx.fillStyle='#ffe2a0';ctx.fillText('◆',e.x,e.y-1.6);}ctx.restore();};
showSelection=function(id){ecoOld.showSelection(id);const e=entities.find(e=>e.id===selectedId);if(e?.kind==='human'){const panel=$('selection');if(panel){const detail=document.createElement('div');detail.innerHTML='<p>'+jobNames[e.job]+' · '+(e.cargo?'Đang mang '+e.cargo.amount.toFixed(1)+' '+resourceNames[e.cargo.type]:'Không mang hàng')+'<br>Trang bị: '+['tool','weapon','armor'].filter(k=>e.equipment[k]).map(k=>resourceNames[k]).join(', ')+'</p>';panel.append(detail);}}};
function renderEconomyHud(){const b=$('economy-open');if(b)b.textContent='⛏ Kinh tế · '+buildings.length;}
function renderEconomy(){const select=$('economy-village');if(!select)return;const wanted=select.value;select.replaceChildren();for(const v of villages){const option=document.createElement('option');option.value=v.id;option.textContent=v.name;select.append(option);}if(villages.some(v=>String(v.id)===wanted))select.value=wanted;const v=villages.find(v=>String(v.id)===String(select.value))||villages[0];if(!v){$('economy-content').innerHTML='<p>Thả cư dân để lập khu định cư đầu tiên.</p>';return;}ensureVillageEconomy(v);$('economy-focus').value=v.focus;$('economy-auto').checked=v.autoBuild;
$('economy-content').innerHTML='<div class="resource-grid">'+Object.entries({food:'Thức ăn',wood:'Gỗ',...resourceNames}).map(([k,n])=>'<div><small>'+n+'</small><b>'+Math.floor(readMaterial(v,k))+'</b></div>').join('')+'</div><p>Kho chứa '+resourceCap(v)+' mỗi loại khoáng sản · Công nghệ: '+techNames[v.tech]+'</p><p>'+Object.entries(jobNames).map(([k,n])=>n+': '+humans().filter(e=>e.village===v.id&&e.job===k).length).join(' · ')+'</p><h3>Công trình</h3><div class="economy-actions">'+Object.entries(buildingDefs).map(([k,d])=>'<button data-construction="'+k+'" '+(hasBuilding(v,k)||v.tech<d.tech||!canAfford(v,d.cost)?'disabled':'')+'><b>'+d.name+(hasBuilding(v,k)?' ✓':'')+'</b><small>'+costText(d.cost)+(v.tech<d.tech?' · Cần '+techNames[d.tech]:'')+'</small></button>').join('')+'</div><h3>Rèn trang bị</h3><p>Dụng cụ tăng khai thác; vũ khí tăng sát thương; giáp giảm sát thương nhận. Trang bị được cấp tự động cho thợ và chiến binh.</p><div class="economy-actions">'+Object.entries(craftDefs).map(([k,c])=>'<button data-craft="'+k+'" '+(!hasBuilding(v,'forge')||!canAfford(v,c.cost)?'disabled':'')+'><b>'+resourceNames[k]+'</b><small>'+costText(c.cost)+'</small></button>').join('')+'</div><p class="dialog-note">Quặng cạn dần khi khai thác. Chợ trao đổi vật liệu với khu định cư có chợ trong hòa bình. Giếng hồi phục dân; tháp canh bảo vệ khu định cư; nhà nghiên cứu tăng tri thức; nhà cá tạo thức ăn gần nước.</p>';
for(const b of $('economy-content').querySelectorAll('[data-construction]'))b.onclick=()=>{try{buildStructure(v.id,b.dataset.construction);}catch(e){toast(e.message);}renderEconomy();};for(const b of $('economy-content').querySelectorAll('[data-craft]'))b.onclick=()=>{try{craft(v.id,b.dataset.craft);}catch(e){toast(e.message);}renderEconomy();};}
function buildEconomyUI(){const b=document.createElement('button');b.id='economy-open';b.textContent='⛏ Kinh tế';$('god-open').parentElement.append(b);const holder=document.createElement('div');holder.innerHTML='<dialog id="economy-dialog" class="wide-dialog"><button class="close" aria-label="Đóng">×</button><span class="dialog-kicker">TỪ MẠCH QUẶNG ĐẾN NỀN VĂN MINH</span><h2>Tài nguyên & nghề nghiệp</h2><label>Khu định cư<select id="economy-village"></select></label><label>Ưu tiên phát triển<select id="economy-focus"><option value="balanced">Cân bằng</option><option value="mining">Khai khoáng</option><option value="farming">Lương thực</option></select></label><label class="law-row"><input id="economy-auto" type="checkbox"><span>Tự xây khi đủ tài nguyên</span></label><div id="economy-content"></div></dialog>';document.body.append(holder);b.onclick=()=>{renderEconomy();$('economy-dialog').showModal();};holder.querySelector('.close').onclick=()=>$('economy-dialog').close();$('economy-village').onchange=renderEconomy;for(const id of ['economy-focus','economy-auto'])$(id).onchange=()=>{const v=villages.find(v=>String(v.id)===$('economy-village').value);if(v){v.focus=$('economy-focus').value;v.autoBuild=$('economy-auto').checked;}};for(const [name,label] of [['resources','Khoáng sản'],['build','Công trình']]){const nav=document.createElement('button');nav.dataset.tab=name;nav.textContent=label;$('tabs').append(nav);nav.onclick=()=>{tab=name;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b===nav));renderTools();};}}
snapshot=function(){return{...ecoOld.snapshot(),version:3,buildings:JSON.parse(JSON.stringify(buildings))};};
function validateEconomy(d){const finite=(n,max=1e6)=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=max;if(!Array.isArray(d.grid)||!d.grid.every(t=>(t.road===undefined||typeof t.road==='boolean')&&(!t.ore||oreKinds.includes(t.ore.type)&&finite(t.ore.initial,10000)&&finite(t.ore.amount,t.ore.initial))))throw Error('Mạch quặng không hợp lệ.');if(!d.villages.every(v=>v.stock&&Object.keys(resourceNames).every(k=>finite(v.stock[k]))&&['balanced','mining','farming'].includes(v.focus)&&typeof v.autoBuild==='boolean'&&finite(v.production)))throw Error('Kho vật liệu không hợp lệ.');if(!d.entities.every(e=>e.kind!=='human'||Object.hasOwn(jobNames,e.job)&&e.equipment&&['weapon','armor','tool'].every(k=>[0,1].includes(e.equipment[k]))&&(!e.cargo||oreKinds.includes(e.cargo.type)&&finite(e.cargo.amount,100))))throw Error('Nghề nghiệp không hợp lệ.');if(!Array.isArray(d.buildings)||d.buildings.length>800||d.buildings.some(b=>b.id>=d.idCounter)||new Set(d.buildings.map(b=>b.id)).size!==d.buildings.length||!d.buildings.every(b=>Number.isInteger(b.id)&&Object.hasOwn(buildingDefs,b.kind)&&d.villages.some(v=>v.id===b.village)&&finite(b.x,W-.001)&&finite(b.y,H-.001)&&finite(b.hp,100)))throw Error('Công trình không hợp lệ.');}
restore=function(input){const d=JSON.parse(JSON.stringify(input));if(!d||![1,2,3].includes(d.version))throw Error('Phiên bản không hỗ trợ.');const v=d.version;if(v===3){validateEconomy(d);d.version=2;}ecoOld.restore(d);buildings=v===3?d.buildings:[];initEconomy(v<3);productionTimer=tradeTimer=autoBuildTimer=0;renderEconomyHud();if($('economy-dialog').open)renderEconomy();};
buildEconomyUI();initEconomy(true);renderEconomyHud();renderTools();
const ecoState=window.mamWorld.getState;
window.mamWorld={...window.mamWorld,newWorld:(...a)=>newWorld(...a),simulate:(...a)=>simulate(...a),snapshot:()=>snapshot(),restore:d=>restore(d),applyTool:(...a)=>applyTool(...a),buildStructure,craft,getEconomy:()=>({villages:JSON.parse(JSON.stringify(villages.map(v=>({id:v.id,name:v.name,food:v.food,wood:v.wood,stock:v.stock})))),buildings:JSON.parse(JSON.stringify(buildings)),deposits:grid.filter(t=>t.ore?.amount>0).length}),getState:()=>({...ecoState(),buildings:buildings.length,deposits:grid.filter(t=>t.ore?.amount>0).length})};
if(document.modelContext?.registerTool)for(const t of [{name:'read_economy',description:'Read village inventories, buildings and remaining mineral deposits.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.mamWorld.getEconomy()},{name:'select_economy_tool',description:'Select a mineral, structure, road or new race brush used by the game toolbar.',inputSchema:{type:'object',properties:{tool:{type:'string',enum:[...groups.resources,...groups.build,...groups.life.filter(t=>['goblin','beastkin'].includes(t[0]))].map(t=>t[0])}},required:['tool'],additionalProperties:false},execute:input=>{const group=Object.keys(groups).find(k=>groups[k].some(t=>t[0]===input?.tool));if(!group||![...groups.resources,...groups.build,...groups.life.filter(t=>['goblin','beastkin'].includes(t[0]))].some(t=>t[0]===input.tool))throw Error('Công cụ không hợp lệ.');tab=group;document.querySelectorAll("[data-tab]").forEach(b=>b.classList.toggle("active",b.dataset.tab===tab));renderTools();choose(input.tool);return window.mamWorld.getState();}}])try{Promise.resolve(document.modelContext.registerTool(t)).catch(()=>{});}catch{}
